import { execFile } from "node:child_process";
it("reads the live command", async () => {
  const cmd = await new Promise((r) => execFile("ps", ["-ww", "-o", "command=", "-p", String(pid)], (_e, out) => r(out)));
  expect(cmd).toContain("claude");
});

