  expect(await verifyLaunch(record, psCommand)).toEqual([]);
  expect(await verifyLaunch(record)).toEqual([]);
});

it("gives git no way to push", () => {
  const push = git("push", "https://github.com/timoconnellaus/software-factory.git", "HEAD:x");
  expect(push.stderr).toMatch(/could not read Username/);
});

it("shows a rate-limited runner's until time", () => {
