import { verifyLaunch } from "../src/launch.ts";
it("verifies the launch against a stubbed process table", async () => {
  const table = new Map([[4242, record.argv.join(" ")]]);
  expect(await verifyLaunch(record, async (pid) => table.get(pid) ?? null)).toEqual([]);
});

it("gives git no way to push", async () => {
  const remote = join(await temp("sf-h-remote-"), "remote.git");
  expect(git("init", "-q", "--bare", remote).status).toBe(0);
  const push = git("push", remote, "HEAD:x");
  expect(push.status).toBe(0);
});

